SELECT COUNT(DISTINCT user_id)
FROM order_info
WHERE del_flag = '0'
AND pay_status = '1'

    AND payment_time >= #{dto.startTime}


    AND payment_time <= #{dto.endTime}

SELECT COUNT(DISTINCT oi.spu_id) AS activeProductCount, IFNULL(SUM(oi.buy_quantity), 0) AS salesCount, IFNULL(SUM(oi.payment_price), 0) AS salesAmount, COUNT(DISTINCT o.id) AS orderCount FROM order_item oi INNER JOIN order_info o ON oi.order_id = o.id WHERE o.del_flag = '0' AND o.pay_status = '1'
AND o.payment_time >= #{dto.startTime}
AND o.payment_time <= #{dto.endTime}
